export const TEMPLATE_FILES: Record<string, string> = {
  "contrast/_brand.yml": "# quarto-deck template \"contrast\": high contrast for large rooms and printed\n# hand-outs. White, black, one strong accent, larger small print, Atkinson\n# Hyperlegible.\nmeta:\n  name: contrast\ncolor:\n  palette:\n    black: \"#000000\"\n    white: \"#FFFFFF\"\n    cobalt: \"#0038A8\"\n    green: \"#006B2D\"\n    red: \"#B00020\"\n    grey: \"#3D3D3D\"\n    ink: \"#000000\"\n    pill: \"#E6E6E6\"\n    rule: \"#000000\"\n    highlight: \"#FFE066\"\n  primary: cobalt\n  success: green\n  danger: red\n  foreground: black\n  background: white\ntypography:\n  base: Atkinson Hyperlegible\n  headings: Atkinson Hyperlegible\n",
  "contrast/theme.scss": "/*-- scss:defaults --*/\n// quarto-deck template \"contrast\": high contrast for large rooms and printed\n// hand-outs. White, black, one strong accent, heavier type and larger\n// small print. Atkinson Hyperlegible (designed for low-vision readers).\n@import url('https://fonts.googleapis.com/css2?family=Atkinson+Hyperlegible:wght@400;700&family=IBM+Plex+Sans:wght@400;500;600;700&display=swap');\n\n// Diagram text keeps a narrower face: SVG layouts are measured for it.\n$qd-font-diagram: \"IBM Plex Sans\", $qd-font-base, sans-serif;\n\n$qd-heading: #000000;\n$qd-statement: #000000;\n$qd-strong: $qd-primary;\n$qd-dim: #3D3D3D;\n$qd-src-size: 0.55em;\n$qd-small-size: 0.6em;\n$qd-top-bar: 8px;\n\n/*-- scss:rules --*/\n.reveal h2 { font-weight: 700; }\n.reveal section:not(.statement):not(.section):not(.dark):not(.plain) > h2 {\n  padding-bottom: 0.15em; border-bottom: 4px solid $qd-accent;\n}\n.reveal figcaption, .reveal .caption { font-size: 0.75em; }\n.reveal .slide-number { font-size: 0.7em; color: #000; }\n// minimum sizes for the small classes of deck-base.html\n.reveal .plab { font-size: 0.48em !important; }\n.reveal .cred, .reveal .credit-photo span { font-size: 0.5em !important; }\n",
  "dark/_brand.yml": "# quarto-deck template \"dark\": dark slate background, light text, teal\n# accent. For evening talks and projectors in dim rooms.\nmeta:\n  name: dark\ncolor:\n  palette:\n    slate: \"#0F172A\"\n    slate-light: \"#1E293B\"\n    paper: \"#E2E8F0\"\n    white: \"#F8FAFC\"\n    teal: \"#2DD4BF\"\n    teal-deep: \"#115E59\"\n    green: \"#4ADE80\"\n    red: \"#F87171\"\n    grey: \"#94A3B8\"\n    accent: \"#2DD4BF\"\n    ink: \"#F1F5F9\"\n    surface: \"#1E293B\"\n    pill: \"#334155\"\n    rule: \"#334155\"\n    highlight: \"#5EEAD4\"\n    section: \"#115E59\"\n    on-section: \"#F8FAFC\"\n  primary: teal\n  success: green\n  danger: red\n  foreground: paper\n  background: slate\ntypography:\n  base: Inter\n  headings: Inter\n",
  "dark/theme.scss": "/*-- scss:defaults --*/\n// quarto-deck template \"dark\": dark slate background, light text, teal\n// accent; for evening talks and projectors in dim rooms. Inter.\n@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=IBM+Plex+Sans:wght@400;500;600;700&display=swap');\n\n// Diagram text keeps a narrower face: SVG layouts are measured for it.\n$qd-font-diagram: \"IBM Plex Sans\", $qd-font-base, sans-serif;\n\n$qd-heading: #F1F5F9;\n$qd-statement: #F1F5F9;\n$qd-strong: $qd-accent;\n$qd-title-tick: true;\n$qd-logo-invert: always;\n\n/*-- scss:rules --*/\n// Content made for a light page (figures, hand-drawn SVG with dark text,\n// transparent PNG layers) sits on a light card, so it stays legible. Not on\n// slides that set their own dark background (reveal marks them\n// .has-dark-background), and not for diagrams slide_add drew with this\n// palette (data-bg=\"dark\").\n.reveal section:not(.has-dark-background) img:not(.slide-logo),\n.reveal section:not(.has-dark-background) svg:not([data-bg=\"dark\"]) {\n  background: #F8FAFC; border-radius: 10px;\n}\n.reveal .slides section .src { color: #CBD5E1; }\n.reveal pre, .reveal code { background: #1E293B; color: #E2E8F0; }\n",
  "neutral/_brand.yml": "# quarto-deck template \"neutral\": plain academic. White background,\n# near-black text, one blue accent, Source Sans Pro.\nmeta:\n  name: neutral\ncolor:\n  palette:\n    blue: \"#1D4E89\"\n    green: \"#2F7A3D\"\n    red: \"#B3261E\"\n    grey: \"#5F6B7A\"\n    near-black: \"#1F2328\"\n    white: \"#FFFFFF\"\n  primary: blue\n  success: green\n  danger: red\n  foreground: near-black\n  background: white\ntypography:\n  base: Source Sans Pro\n  headings: Source Sans Pro\n",
  "neutral/theme.scss": "/*-- scss:defaults --*/\n// quarto-deck template \"neutral\": plain academic. White background,\n// near-black text, one blue accent, Source Sans Pro (bundled with Quarto,\n// so it works offline). No bars, no ticks.\n\n$qd-heading: $qd-fg;\n$qd-statement: $qd-fg;\n$qd-strong: $qd-primary;\n\n/*-- scss:rules --*/\n// titles get a hairline instead of a tick\n.reveal section:not(.statement):not(.section):not(.dark):not(.plain) > h2 {\n  padding-bottom: 0.18em; border-bottom: 1px solid $qd-rule;\n}\n",
  "sample/backdrop.svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 900\" width=\"800\" height=\"900\">\n  <defs><linearGradient id=\"g\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop offset=\"0\" stop-color=\"#9FB7C9\"/><stop offset=\"1\" stop-color=\"#3E5C76\"/></linearGradient></defs>\n  <rect width=\"800\" height=\"900\" fill=\"url(#g)\"/>\n  <circle cx=\"420\" cy=\"380\" r=\"210\" fill=\"#ffffff\" fill-opacity=\"0.18\"/>\n  <circle cx=\"560\" cy=\"620\" r=\"130\" fill=\"#ffffff\" fill-opacity=\"0.12\"/>\n</svg>\n",
  "sample/figure.svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 520\" width=\"900\" height=\"520\" font-family=\"Helvetica, Arial, sans-serif\">\n  <rect width=\"900\" height=\"520\" fill=\"#ffffff\"/>\n  <text x=\"20\" y=\"34\" font-size=\"28\" font-weight=\"700\">A</text>\n  <line x1=\"110\" y1=\"440\" x2=\"860\" y2=\"440\" stroke=\"#000\" stroke-width=\"2\"/>\n  <line x1=\"110\" y1=\"60\" x2=\"110\" y2=\"440\" stroke=\"#000\" stroke-width=\"2\"/>\n  <g font-size=\"20\" text-anchor=\"end\">\n    <text x=\"100\" y=\"446\">0</text><text x=\"100\" y=\"351\">25</text><text x=\"100\" y=\"256\">50</text><text x=\"100\" y=\"161\">75</text><text x=\"100\" y=\"66\">100</text>\n  </g>\n  <text x=\"40\" y=\"250\" font-size=\"22\" transform=\"rotate(-90 40 250)\" text-anchor=\"middle\">Survival (%)</text>\n  <g fill=\"#444\"><rect x=\"170\" y=\"98\" width=\"110\" height=\"342\"/><rect x=\"420\" y=\"190\" width=\"110\" height=\"250\"/><rect x=\"670\" y=\"300\" width=\"110\" height=\"140\"/></g>\n  <g font-size=\"22\" text-anchor=\"middle\"><text x=\"225\" y=\"474\">control</text><text x=\"475\" y=\"474\">low dose</text><text x=\"725\" y=\"474\">high dose</text></g>\n  <text x=\"485\" y=\"510\" font-size=\"20\" text-anchor=\"middle\">Sample figure drawn for the template preview</text>\n</svg>\n",
  "shared/deck-base.html": "<!-- quarto-deck structural classes, shared by every template.\n     Colours and fonts are CSS variables (--qd-*) that the template's\n     theme/<template>.scss defines from _brand.yml. Do not put hex values\n     here: switch the look with template_apply, not by editing this file.\n     Loaded via YAML: include-in-header: theme/deck-base.html -->\n<style>\n/* source line under a figure */\n.reveal .src {\n  display: block; font-size: var(--qd-src-size, 0.45em); color: var(--qd-dim);\n  text-align: left; margin-top: 0.25em;\n}\n\n/* figures never push a slide past its height */\n.reveal .r-stretch { max-height: 520px; width: auto; display: block; margin: 0 auto; }\n.reveal img { background: transparent; border: none; box-shadow: none; }\n\n/* placeholder for a figure still to insert */\n.reveal .ph {\n  display: flex; align-items: center; justify-content: center;\n  height: 430px; margin: 0.4em auto; max-width: 1000px;\n  border: 3px dashed var(--qd-accent); border-radius: 10px;\n  background: color-mix(in srgb, var(--qd-accent) 5%, transparent);\n}\n.reveal .ph p { margin: 0; padding: 0 1.4em; font-size: 0.62em; color: var(--qd-heading); line-height: 1.45; }\n.reveal .ph strong { color: var(--qd-accent-ink); }\n\n/* learning outcomes: numbered, roomy, readable from the back */\n.reveal .lo, .reveal .lo ol, .reveal ol.lo { font-size: 0.88em; line-height: 1.4; margin-left: 0.5em; }\n.reveal .lo li, .reveal ol.lo li { margin-bottom: 0.5em; }\n.reveal .lo li strong, .reveal ol.lo li strong { color: var(--qd-accent-ink); }\n\n/* exam-style practice question */\n.reveal .exam { font-size: 0.62em; line-height: 1.4; }\n.reveal .exam ol { margin-left: 0.5em; }\n.reveal .exam li { margin-bottom: 0.3em; }\n.reveal .exam .stem { color: var(--qd-dim); margin-bottom: 0.5em; }\n\n/* CV / introduction slide */\n.reveal .side { font-size: 0.72em; line-height: 1.35; }\n.reveal .side li { margin-bottom: 0.22em; }\n.reveal .side ul { margin-top: 0.15em; }\n\n/* learning outcomes revisited: ticked list */\n.reveal .lo-done, .reveal .lo-done ol, .reveal ol.lo-done { font-size: 0.86em; line-height: 1.38; margin-left: 0.5em; list-style: none; }\n.reveal .lo-done li, .reveal ol.lo-done li { margin-bottom: 0.5em; text-indent: -1.5em; padding-left: 1.5em; }\n.reveal .lo-done li::before, .reveal ol.lo-done li::before {\n  content: \"\\2713\\00a0\\00a0\"; color: var(--qd-accent); font-weight: 800;\n}\n.reveal .lo-done li strong, .reveal ol.lo-done li strong { color: var(--qd-accent-ink); }\n\n/* a statement slide that needs smaller type than the default */\n.reveal section.statement.sm p { font-size: 1.45em; line-height: 1.3; }\n\n/* in-lecture drawing activity */\n.reveal .task {\n  font-size: 0.66em; line-height: 1.45; color: var(--qd-heading);\n  max-width: 1080px; margin: 0 auto 0.35em;\n}\n.reveal .task strong { color: var(--qd-accent-ink); }\n/* .ask: a question slide, read from the back of the room */\n.reveal .task.ask { font-size: 1.1em; line-height: 1.5; max-width: 1140px; }\n.reveal .task.ask p { margin: 0.8em 0; }\n.reveal .canvas {\n  position: relative; height: 300px; max-width: 1080px; margin: 0 auto;\n  border: 3px dashed var(--qd-accent); border-radius: 10px;\n  background: color-mix(in srgb, var(--qd-accent) 4%, transparent);\n}\n.reveal .canvas .hint {\n  position: absolute; bottom: 10px; left: 0; right: 0;\n  text-align: center; font-size: var(--qd-small-size, 0.5em); color: var(--qd-dim);\n}\n.reveal .wordbank {\n  display: flex; gap: 0.5em; justify-content: center; flex-wrap: wrap;\n  position: absolute; top: 16px; left: 0; right: 0;\n}\n.reveal .wordbank span {\n  background: var(--qd-primary); color: var(--qd-on-primary); border-radius: 6px;\n  padding: 0.18em 0.6em; font-size: 0.52em; font-weight: 600;\n}\n\n/* inline SVG diagrams fill the slide body and stay crisp */\n.reveal svg.diagram { display: block; width: 100%; max-height: 520px; margin: 0 auto; }\n.reveal svg.diagram text { font-family: var(--qd-font-diagram, var(--qd-font-body)); }\n\n/* small credit, bottom right: a person and a year */\n.reveal .cred {\n  position: absolute; right: 36px; bottom: 26px;\n  font-size: 0.42em; color: var(--qd-dim); letter-spacing: 0.02em;\n}\n/* one worked example under a claim */\n.reveal .example {\n  font-size: 0.55em; line-height: 1.4; color: var(--qd-heading);\n  border-left: 5px solid var(--qd-accent); padding: 0.15em 0 0.15em 0.7em;\n  margin-top: 0.5em;\n}\n.reveal .example strong { color: var(--qd-accent-ink); }\n/* three short claims, large enough to read from the back */\n.reveal .claims p { font-size: 0.74em; line-height: 1.45; margin: 0.42em 0; color: var(--qd-heading); }\n.reveal .claims strong { color: var(--qd-accent-ink); }\n\n/* two-theory comparison table */\n.reveal .cmp table { width: 100%; border-collapse: collapse; font-size: 0.80em; margin: 0.1em 0; }\n.reveal .cmp th, .reveal .cmp td {\n  border: none; border-bottom: 2px solid var(--qd-rule);\n  padding: 0.5em 0.7em; vertical-align: top; text-align: left; line-height: 1.32;\n}\n.reveal .cmp thead th { background: var(--qd-primary); color: var(--qd-on-primary); font-weight: 700; border-bottom: none; }\n.reveal .cmp thead th:first-child { background: transparent; color: var(--qd-heading); }\n.reveal .cmp colgroup { display: none; }\n.reveal .cmp tbody td:first-child { font-weight: 700; color: var(--qd-heading); width: 20% !important; }\n.reveal .cmp tbody td:nth-child(2) { color: var(--qd-dim); width: 38% !important; }\n.reveal .cmp tbody td:nth-child(3) { color: var(--qd-heading); width: 42% !important; background: color-mix(in srgb, var(--qd-accent) 7%, transparent); }\n\n/* four-column variant: last column is the result and gets the accent wash */\n.reveal .cmp.four thead th:first-child { color: var(--qd-heading); background: transparent; }\n.reveal .cmp.four tbody td:first-child { width: 22% !important; }\n.reveal .cmp.four tbody td:nth-child(2) { width: 16% !important; color: var(--qd-accent-ink); font-weight: 700; background: none; }\n.reveal .cmp.four tbody td:nth-child(3) { width: 36% !important; color: var(--qd-dim); background: none; }\n.reveal .cmp.four tbody td:nth-child(4) { width: 26% !important; color: var(--qd-heading); font-weight: 700; background: color-mix(in srgb, var(--qd-accent) 7%, transparent); }\n\n/* .cmp.four.after: the SECOND data column is the result, so emphasise column 3, not 2 */\n.reveal .cmp.four.after tbody td:nth-child(2) { color: var(--qd-dim); font-weight: 400; }\n.reveal .cmp.four.after tbody td:nth-child(3) { color: var(--qd-accent-ink); font-weight: 700; }\n\n/* three uniform portrait tiles */\n.reveal img.portrait {\n  display: block; width: 100%; height: 360px; object-fit: cover;\n  object-position: center 22%; border-radius: 10px; margin: 0 0 0.5em 0;\n}\n.reveal .who { text-align: center; line-height: 1.3; }\n.reveal .who p { margin: 0; }\n.reveal .who .nm { font-size: 0.62em; font-weight: 700; color: var(--qd-heading); }\n.reveal .who .pos { font-size: 0.5em; color: var(--qd-accent-ink); font-weight: 700; }\n\n/* a tall figure that must fit under a two-line title */\n.reveal img.fig-tall { max-height: 470px; width: auto; display: block; margin: 0 auto; }\n\n/* a paper figure under a one-line title, as large as the slide allows */\n.reveal img.fig-xl { max-height: 555px; width: auto; display: block; margin: 0 auto; }\n\n/* credit line laid over a full-bleed photograph, bottom centre */\n.reveal .credit-photo {\n  position: absolute; left: 0; right: 0; bottom: 14px;\n  text-align: center; line-height: 1.3; margin: 0;\n}\n.reveal .credit-photo span {\n  display: inline-block; background: rgba(0, 0, 0, 0.55); color: #fff;\n  font-size: 0.4em; letter-spacing: 0.02em;\n  padding: 0.3em 0.8em; border-radius: 5px;\n}\n\n/* full-bleed figure slides: drop the logo and the footer so nothing sits on the figure */\n.reveal:has(section.bleed.present) .slide-logo,\n.reveal:has(section.bleed.present) .footer,\n.reveal:has(section.bleed.present) div.footer { display: none !important; }\n\n/* four figure panels in a grid */\n.reveal img.panel { max-height: 200px; width: auto; display: block; margin: 0 auto; }\n.reveal .plab { display: block; text-align: center; font-size: 0.38em; color: var(--qd-dim); margin: 0 0 0.12em; }\n\n/* full-height figure under a one-line title */\n.reveal img.fig-max { max-height: 600px; width: auto; display: block; margin: 0 auto; }\n\n.reveal img.legend { max-height: 215px; width: auto; display: block; margin: 2.4em auto 0; }\n</style>\n",
  "shared/defaults.scss": "// ---- quarto-deck shared defaults ---------------------------------------\n// Every value can be set by the template before this block (all !default).\n// The $qd-* colours above come from the deck's _brand.yml.\n$qd-heading: $qd-primary !default;          // h1/h2 colour\n$qd-statement: $qd-heading !default;        // statement-slide sentence\n$qd-dim: $qd-muted !default;                // captions, footer, .src\n$qd-strong: $qd-accent-ink !default;        // **bold** in body text\n$qd-section-text: $qd-on-section !default;  // text on section/.dark slides\n$qd-font-body: $qd-font-base, -apple-system, \"Segoe UI\", sans-serif !default;\n$qd-font-head: $qd-font-headings, $qd-font-body !default;\n$qd-font-diagram: $qd-font-body !default;   // text in svg.diagram\n$qd-top-bar: 0 !default;                    // height of the bar across the top (0 = none)\n$qd-title-tick: false !default;             // short accent bar under slide titles\n$qd-logo-height: 92px !default;\n$qd-logo-invert: dark-slides !default;      // dark-slides | always | never\n$qd-src-size: 0.45em !default;              // source line under a figure\n$qd-small-size: 0.5em !default;             // footer, credits, hints\n\n// Set outright (not !default): Quarto's _brand.yml layer would otherwise\n// win. A template changes these through the $qd-* variables.\n$body-bg: $qd-bg;\n$body-color: $qd-fg;\n$link-color: $qd-accent-ink;\n$link-color-hover: $qd-accent;\n$selection-bg: rgba($qd-accent, 0.22);\n$font-family-sans-serif: $qd-font-body;\n$presentation-heading-font: $qd-font-head;\n$presentation-heading-color: $qd-heading;\n\n$presentation-font-size-root: 34px !default;\n$presentation-line-height: 1.4 !default;\n$presentation-heading-font-weight: 700 !default;\n$presentation-h1-font-size: 2.0em !default;\n$presentation-h2-font-size: 1.35em !default;\n$presentation-h3-font-size: 1.05em !default;\n$code-block-font-size: 0.7em !default;\n",
  "shared/rules.scss": "// ---- quarto-deck shared rules ------------------------------------------\n// Structure every template shares; colours only through $qd-* variables.\n// The same values are exposed as CSS variables (--qd-*) for deck-base.html.\n:root {\n  --qd-primary: #{$qd-primary};\n  --qd-on-primary: #{$qd-on-primary};\n  --qd-good: #{$qd-good};\n  --qd-bad: #{$qd-bad};\n  --qd-muted: #{$qd-muted};\n  --qd-dim: #{$qd-dim};\n  --qd-ink: #{$qd-ink};\n  --qd-surface: #{$qd-surface};\n  --qd-pill: #{$qd-pill};\n  --qd-highlight: #{$qd-highlight};\n  --qd-bg: #{$qd-bg};\n  --qd-fg: #{$qd-fg};\n  --qd-accent: #{$qd-accent};\n  --qd-accent-ink: #{$qd-accent-ink};\n  --qd-strong: #{$qd-strong};\n  --qd-rule: #{$qd-rule};\n  --qd-section: #{$qd-section};\n  --qd-on-section: #{$qd-on-section};\n  --qd-heading: #{$qd-heading};\n  --qd-font-body: #{$qd-font-body};\n  --qd-font-diagram: #{$qd-font-diagram};\n  --qd-src-size: #{$qd-src-size};\n  --qd-small-size: #{$qd-small-size};\n}\n\n.reveal h1, .reveal h2, .reveal h3, .reveal h4 {\n  text-transform: none; letter-spacing: -0.015em;\n}\n\n// Title = message, left-aligned.\n.reveal h2 {\n  text-align: left; line-height: 1.12; margin-bottom: 0.55em;\n}\n\n@if $qd-title-tick {\n  // Short accent tick under the title (not on statement/section/dark/plain).\n  $tkbase: \"section:not(.statement):not(.section):not(.dark):not(.plain)\";\n  // `>`: an enclosing stack section must not give a statement slide a tick\n  .reveal #{$tkbase} > h2::after {\n    content: \"\"; display: block; width: 1.6em; height: 6px;\n    background: $qd-accent; border-radius: 3px; margin-top: 0.2em;\n  }\n}\n// Entry animations, (re)triggered per slide by deck JS toggling\n// .title-anim / .tick-anim.\n@keyframes tickDraw       { from { width: 0; } to { width: 1.6em; } }\n@keyframes tickDrawCenter { from { clip-path: inset(0 50% 0 50%); } to { clip-path: inset(0 0 0 0); } }\n@keyframes titleRise      { from { opacity: 0; transform: translateY(13px); } to { opacity: 1; transform: translateY(0); } }\n@keyframes tickPulse      { 0%,100% { box-shadow: 0 0 0 0 rgba($qd-accent, 0); } 45% { box-shadow: 0 0 0 7px rgba($qd-accent, 0.32); } }\n.reveal h2.title-anim { animation: titleRise 0.55s ease 0.12s both; }\n.reveal h2.tick-anim::after { animation: tickDraw 0.75s cubic-bezier(.3,.7,.2,1) 0.4s both; }\n.reveal section.tick-center h2.tick-anim::after { animation: tickDrawCenter 0.75s ease 0.4s both; }\n.reveal section.tick-pulse  h2.tick-anim::after {\n  animation: tickDraw 0.75s cubic-bezier(.3,.7,.2,1) 0.4s both,\n             tickPulse 1.1s ease 1.2s 1;\n}\n\n// BIG-NUMBER: one huge stat on a {.center .plain} slide.\n.reveal .bignum {\n  display: block; text-align: center; font-size: 5em; line-height: 1;\n  font-weight: 800; letter-spacing: -0.02em; margin: 0 0 0.15em;\n}\n.reveal .bignum-cap { display: block; text-align: center; color: $qd-dim; font-size: 1.05em; }\n.reveal section.plain h2:empty { display: none; }\n\n.reveal strong { color: $qd-strong; font-weight: 700; }\n.reveal a { color: $qd-accent-ink; text-decoration: none; }\n.reveal a:hover { color: $qd-accent; text-decoration: underline; }\n.reveal .progress { color: $qd-accent; height: 3px; }\n.reveal .controls { color: $qd-primary; }\n.reveal blockquote {\n  background: none; border: none; border-left: 3px solid $qd-accent;\n  padding: 0 0 0 0.8em; margin-left: 0; font-style: normal; box-shadow: none;\n}\n.reveal img { background: transparent; border: none; box-shadow: none; }\n.reveal figcaption, .reveal .caption { color: $qd-dim; font-size: 0.7em; }\n.reveal .footer { color: $qd-dim; font-size: $qd-small-size; }\n.reveal .slide-number { background: transparent; color: $qd-dim; }\n\n@if $qd-top-bar != 0 {\n  // a persistent thin accent bar across the top of the deck\n  .reveal::after {\n    content: \"\"; position: fixed; top: 0; left: 0; right: 0; height: $qd-top-bar;\n    background: $qd-accent; z-index: 60; pointer-events: none;\n  }\n}\n\n// Logo bottom right; the slide number moves left so it is not under it\n.reveal .slide-logo {\n  max-height: $qd-logo-height !important; height: $qd-logo-height !important;\n  bottom: 18px !important; right: 24px !important; left: auto !important;\n}\n// The slide number stays where Quarto puts it (top left with a logo). Do not\n// move it to the bottom-left corner: the menu button (three stripes) sits\n// there, and the number would cover it so clicks never reach the menu.\n@if $qd-logo-invert == dark-slides {\n  // reveal adds .has-dark-background to .reveal on dark slides → white logo\n  .reveal.has-dark-background .slide-logo { filter: brightness(0) invert(1); }\n} @else if $qd-logo-invert == always {\n  .reveal .slide-logo { filter: brightness(0) invert(1); }\n}\n\n// STATEMENT: big, centred, bounded so it never falls off the slide.\n.reveal section.statement,\n.reveal section.statement h2,\n.reveal section.statement p { text-align: center; }\n.reveal section.statement h2 { font-weight: 800; }\n.reveal section.statement p {\n  font-size: 2.6em; line-height: 1.12; font-weight: 800;\n  color: $qd-statement; margin: 0;\n}\n.reveal section.statement strong { color: $qd-accent; }\n\n// Dark slides: section dividers and .dark (background set per slide).\n.reveal section.section, .reveal section.dark,\n.reveal section.section h1, .reveal section.section h2, .reveal section.section p,\n.reveal section.dark h1, .reveal section.dark h2, .reveal section.dark p {\n  color: $qd-section-text !important;\n}\n.reveal section.section h1, .reveal section.section h2 { text-align: center; }\n.reveal section.dark h2 { text-align: center; }\n.reveal section.section strong, .reveal section.dark strong { color: $qd-accent; }\n\n.reveal .title-slide h1.title { color: $qd-heading; }\n.reveal .title-slide .subtitle, .reveal .title-slide .author,\n.reveal .title-slide .date { color: $qd-dim; }\n",
  "wur/_brand.yml": "# quarto-deck template \"wur\": Wageningen University & Research look\n# (navy + Wageningen green, Archivo headings, IBM Plex Sans body).\n# The WUR logo is not shipped: pass logo= to deck_init / template_apply.\nmeta:\n  name: wur\ncolor:\n  palette:\n    navy: \"#12384A\"\n    green: \"#34B233\"\n    green-ink: \"#2E8B2C\"\n    green-dark: \"#2E7D32\"\n    red: \"#C0392B\"\n    grey: \"#6B6B6B\"\n    off-white: \"#FAFAF7\"\n    near-black: \"#1A1A1A\"\n    accent: \"#34B233\"\n    accent-ink: \"#2E8B2C\"\n    ink: \"#12384A\"\n    surface: \"#FFFFFF\"\n    pill: \"#E3E8EB\"\n    rule: \"#E6EBEE\"\n    highlight: \"#CFE8C4\"\n    on-primary: \"#FFFFFF\"\n    on-section: \"#FFFFFF\"\n    title-slide: \"#12384A\"\n    tint-good: \"#EEF5EA\"\n    tint-bad: \"#FBEDEB\"\n    tint-neutral: \"#EEF2F4\"\n    tint-muted: \"#F2F2F2\"\n  primary: navy\n  success: green-dark\n  danger: red\n  foreground: near-black\n  background: off-white\ntypography:\n  base: IBM Plex Sans\n  headings: Archivo\n",
  "wur/theme.scss": "/*-- scss:defaults --*/\n// quarto-deck template \"wur\": Wageningen University & Research look.\n// Navy + Wageningen green, logo bottom right, thin green bar along the top,\n// short green tick under every title. Headings Archivo, body IBM Plex Sans.\n@import url('https://fonts.googleapis.com/css2?family=Archivo:wght@500;600;700;800&family=IBM+Plex+Sans:wght@400;500;600;700&display=swap');\n\n$qd-top-bar: 6px;\n$qd-title-tick: true;\n$qd-section-text: $qd-bg;                   // off-white on navy dividers\n\n/*-- scss:rules --*/\n"
};
